// CPR/First Aid Practice Test 1. Original questions written for Valus, modeled on the
// HOSA 2026–27 Round One test plan (Basic Life Support 40%, First Aid 60%) and sample items.
// Content follows the AHA 2025 and ARC 2025 guidelines the event now uses, at an
// advanced level: physiology behind each step, exact guideline values and multi-step scenarios.
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
// q(topic, prompt, correct option, three wrong options, letter where the correct option goes, explanation, reference)
const q=(topic,prompt,correct,wrong,letter,explain,ref)=>{const at='ABCD'.indexOf(letter);return {topic,prompt,options:[...wrong.slice(0,at),correct,...wrong.slice(at)],answer:at,explain,ref};};
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-1',
 event:'CPR/First Aid',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:[
  q(GEN,'A team reviews data from a 10-minute adult cardiac arrest. Chest compressions were being performed for a total of 7 minutes 30 seconds. Which statement about the team’s chest compression fraction (CCF) is correct?',
   'It is 75%: above the 60% minimum, below the 80% goal',['It is 25%, because CCF measures the time without compressions','It is 75%, which exceeds the AHA goal of at least 70%','It is 75%, which is below the AHA minimum of 90%'],'C',
   'CCF is the share of total resuscitation time spent doing compressions: 7.5 ÷ 10 = 75%. The AHA calls for a CCF of at least 60% and sets a goal of 80% or higher, so this team should shorten pauses for rhythm checks, switches and ventilation.',AHA_BLS),
  q(BASIC,'A first aider begins caring for an injured hiker, then leaves before EMS or another trained person arrives, and the hiker’s condition worsens. Which legal term best describes the first aider’s action?',
   'Abandonment',['Implied consent','Battery','Breach of confidentiality'],'C',
   'Once you begin care, you have a duty to continue until someone with equal or higher training takes over, the scene becomes unsafe, or you are physically unable to continue. Leaving earlier is abandonment. Battery is touching a person without consent.',DHO),
  q(ENV,'Which combination of findings defines exertional heat stroke?',
   'Core temperature above 104 °F (40 °C) with CNS dysfunction',['Core temperature above 100.4 °F (38 °C) with heavy sweating and a rapid pulse','Painful muscle spasms with a normal mental status','Pale, clammy skin, thirst and nausea with a normal mental status'],'A',
   'Heat stroke is a core temperature above about 104 °F (40 °C) together with CNS dysfunction such as confusion, slurred speech, seizures or collapse. The skin may still be sweaty in exertional heat stroke, so a change in mental status, not dry skin, is the key sign.',AHA_FA),
  q(CPR,'A woman who is about 30 weeks pregnant goes into cardiac arrest, and her uterus is palpable above the umbilicus. In addition to high-quality CPR, what should a second rescuer do?',
   'Perform continuous manual left uterine displacement',['Tilt the whole patient 30° onto her right side','Raise her legs to increase blood return to the heart','Delay the AED until fetal heart tones are checked'],'D',
   'When the uterus reaches the umbilicus or higher, it compresses the inferior vena cava and aorta (aortocaval compression), cutting blood return to the heart. Pushing the uterus to the patient’s left by hand relieves this while compressions continue on a flat surface. Defibrillation is not delayed in pregnancy.',AHA_BLS),
  q(INJ,'An adult has partial-thickness burns covering the entire right arm and the entire front of the trunk. Using the rule of nines, about what percentage of total body surface area is burned?',
   '27%',['18%','36%','45%'],'B',
   'In the adult rule of nines, each whole arm is 9% and the front of the trunk is 18%, so 9% + 18% = 27%. Partial-thickness burns over this large an area need EMS, cooling without causing hypothermia, and treatment for shock.',DHO),
  q(MED,'Why is aspirin given to a person with suspected acute coronary syndrome, and how should it be taken?',
   'It inhibits platelets, so it should be chewed',['It dissolves the clot, so it should be placed under the tongue','It relieves the chest pain, so it should be swallowed with water','It dilates coronary arteries, so it should be swallowed whole'],'A',
   'Aspirin blocks platelet aggregation, limiting the growth of the clot in the coronary artery. Chewing it gets it into the blood faster. The dose is one adult aspirin (325 mg) or two to four low-dose (81 mg) aspirin, if the person has no allergy or bleeding risk.',AHA_FA),
  q(AED,'An infant in cardiac arrest is found to have a shockable rhythm. Which defibrillation option is preferred?',
   'A manual defibrillator, or an AED with a pediatric attenuator',['An AED with adult pads, because pediatric pads deliver too little energy','No defibrillation, because infants do not have shockable rhythms','An AED with pediatric pads, both placed on the front of the chest'],'B',
   'For infants, a manual defibrillator is preferred. If one is not available, use an AED with a pediatric dose attenuator, and if that is not available either, use a standard AED. On a small chest, pads go front and back so they do not touch.',AHA_BLS),
  q(BASIC,'An injured patient opens her eyes and moans only when you pinch her trapezius muscle. Using the AVPU scale, how is her level of responsiveness recorded?',
   'Painful',['Alert','Verbal','Unresponsive'],'C',
   'AVPU stands for Alert, responds to Verbal stimulus, responds to Painful stimulus, and Unresponsive. A response only to a painful stimulus is recorded as P and suggests a serious problem that needs EMS.',ARC_FA),
  q(CH,'A responsive woman in the third trimester of pregnancy is choking and cannot speak or cough. What should the rescuer do?',
   'Alternate back blows with chest thrusts',['Alternate back blows with abdominal thrusts','Give abdominal thrusts only, delivered more gently','Give blind finger sweeps between back blows'],'D',
   'In late pregnancy, or when the rescuer cannot wrap their arms around the person’s abdomen, chest thrusts replace abdominal thrusts to avoid injuring the uterus and fetus. Back blows are still alternated with the thrusts under the current AHA and Red Cross guidelines.',AHA_BLS+'; '+ARC_FA),
  q(INJ,'A commercial tourniquet has been tightened 2–3 inches above a thigh wound, but bright red blood is still flowing. What is the next step?',
   'Apply a second tourniquet just above the first',['Loosen the first tourniquet and reapply it lower','Remove the tourniquet and elevate the leg','Press on the femoral pressure point instead'],'A',
   'If one tourniquet does not stop the bleeding, place a second one above (proximal to) the first. A tourniquet is never loosened once it is on. Elevation and pressure points are not recommended for controlling bleeding because there is no evidence that they work.',ARC_FA),
  q(MED,'A man with diabetes has had increasing thirst and urination for two days. He is now drowsy, with fruity-smelling breath and deep, rapid breathing. Which condition is most likely?',
   'Hyperglycemia with diabetic ketoacidosis',['Hypoglycemia from taking too much insulin','An opioid overdose','Heat exhaustion'],'D',
   'High blood sugar develops slowly, over hours to days, with thirst and frequent urination. Ketone build-up causes fruity breath and deep, rapid (Kussmaul) breathing as the body blows off acid. Low blood sugar comes on quickly, with shakiness, sweating and confusion.',DHO),
  q(GEN,'During a resuscitation, the team leader says, “Give naloxone, 4 milligrams intranasal.” What should the team member do to complete closed-loop communication?',
   'Repeat the order back, then say when the dose has been given',['Give the dose without speaking, to keep the room quiet','Nod to the team leader to show the order was heard','Ask another team member to confirm the dose first'],'B',
   'In closed-loop communication, the leader gives a clear order, the team member repeats it back to confirm, and then reports when the task is done. This prevents missed or duplicated medications and keeps the leader aware of what has happened.',AHA_BLS),
  q(ENV,'Lightning strikes a group of hikers. One hiker is moaning and breathing; another is not breathing and has no pulse. Whom should the first aider treat first?',
   'The hiker in cardiac arrest, because lightning victims often respond to CPR',['The moaning hiker, because people who survive the strike come first','Neither, until 30 minutes have passed since the last thunder','The moaning hiker, because cardiac arrest from lightning is not survivable'],'A',
   'Lightning uses reverse triage. People who are breathing after a strike usually recover, while those in cardiac arrest often survive with prompt CPR and defibrillation. Lightning victims carry no electrical charge and are safe to touch.',ARC_FA),
  q(CPR,'Two rescuers are performing CPR on a 7-month-old infant. Which technique and ratio are correct?',
   'Two-thumb encircling-hands technique, 15:2',['Two fingers on the breastbone, 15:2','Heel of one hand, 30:2','Two-thumb encircling-hands technique, 30:2'],'C',
   'With two rescuers, infant CPR uses the two-thumb encircling-hands technique, which produces better pressures, at a 15:2 ratio. The current guidelines no longer teach the two-finger technique. A single rescuer uses 30:2.',AHA_BLS+'; '+ARC_BLS),
  q(INJ,'A stabbing victim has an open chest wound that bubbles with each breath. According to current first aid guidelines, how should it be managed?',
   'Leave it open or use a non-occlusive dressing',['Seal it airtight on all four sides with plastic','Pack gauze deep into the chest wound','Hold a thick pad tightly against it with the hand'],'B',
   'An airtight (occlusive) dressing can trap air in the chest and lead to a tension pneumothorax. Current guidelines advise leaving an open chest wound exposed, or using a non-occlusive dressing, and controlling bleeding with local pressure if needed. Watch for worsening breathing.',AHA_FA),
  q(MED,'Which set of findings most strongly suggests an opioid overdose?',
   'Unresponsiveness, pinpoint pupils and slow or absent breathing',['Agitation, dilated pupils, sweating and a rapid heart rate','Fruity breath, deep rapid breathing and thirst','Hot, flushed skin, confusion and a very high body temperature'],'D',
   'The classic opioid toxidrome is a decreased level of consciousness, constricted (pinpoint) pupils and respiratory depression. Opioids slow the brain’s drive to breathe, which is why naloxone and rescue breathing are the key treatments.',AHA_FA),
  q(ADV,'Two healthcare providers are performing CPR on a 4-year-old who now has an advanced airway in place. How should ventilations be given?',
   '1 breath every 2–3 seconds with continuous compressions',['1 breath every 6 seconds with continuous compressions','2 breaths after every 15 compressions','1 breath every 10 seconds with a pause for each breath'],'A',
   'With an advanced airway in an infant or child, compressions continue without pauses and breaths are given at 1 every 2–3 seconds (20–30 per minute). For adults with an advanced airway, the rate is 1 breath every 6 seconds.',AHA_BLS),
  q(BASIC,'When you press on a 5-year-old’s nail bed and release it, color takes 4 seconds to return. What does this most likely indicate?',
   'Poor perfusion, which may indicate shock',['Normal circulation for a young child','A broken finger on that hand','A normal finding after exercise'],'C',
   'Normal capillary refill is 2 seconds or less. A delay suggests the body is cutting blood flow to the skin to protect vital organs, an early sign of shock in children. Cold surroundings can also slow refill, so judge it together with other signs.',DHO),
  q(AED,'While preparing to attach AED pads, a rescuer sees a medication patch on the patient’s upper right chest where a pad belongs. What should the rescuer do?',
   'Remove the patch with a gloved hand and wipe the skin first',['Place the pad directly over the patch so the shock is not delayed','Leave the patch and continue CPR without the AED','Move the pad to the left side of the chest beside the other pad'],'B',
   'A pad placed over a medication patch can block energy delivery and cause burns. Wearing gloves to avoid absorbing the medication, remove the patch, wipe the area and place the pad without delaying the shock.',AHA_BLS),
  q(INJ,'A burn is white and leathery, and the person feels little pain in the center of it. What type of burn is this?',
   'Full-thickness (third-degree) burn',['Superficial (first-degree) burn','Superficial partial-thickness burn','Deep sunburn with blistering'],'D',
   'Full-thickness burns destroy all layers of the skin, including nerve endings, so the center may be painless and look white, leathery or charred. Partial-thickness burns blister and are very painful. Full-thickness burns always need EMS.',DHO),
  q(CPR,'What compression depth is recommended for a 6-year-old child in cardiac arrest?',
   'At least one-third the chest depth, about 2 inches (5 cm)',['About one-quarter the chest depth, about 1 inch (2.5 cm)','At least 2.4 inches (6 cm), the adult maximum','About one-half the chest depth, about 3 inches (7.5 cm)'],'A',
   'Children need compressions at least one-third the front-to-back depth of the chest, about 2 inches (5 cm). Infants need about 1.5 inches (4 cm). Adults need at least 2 inches but no more than 2.4 inches (5–6 cm).',AHA_BLS),
  q(MED,'Which term describes a seizure lasting longer than 5 minutes, or repeated seizures without the person regaining consciousness between them?',
   'Status epilepticus',['Prolonged postictal state','Complex absence seizure','Febrile seizure'],'B',
   'Status epilepticus is a medical emergency that can cause brain injury and breathing problems, so call 911. The postictal state is the period of drowsiness and confusion after a seizure ends.',DHO),
  q(RB,'An infant is unresponsive and gasping. The brachial pulse is 50 per minute, and the skin stays pale and mottled despite effective rescue breaths. What should the rescuer do?',
   'Begin CPR, starting with chest compressions',['Continue rescue breaths at 1 every 2–3 seconds','Recheck the pulse every 10 seconds before acting','Switch to 1 breath every 6 seconds'],'D',
   'In infants and children, a heart rate below 60 per minute with signs of poor perfusion despite adequate oxygenation and ventilation is treated as cardiac arrest. Begin CPR, because cardiac output depends on heart rate at this age.',AHA_BLS),
  q(ENV,'A hiker with hypothermia has stopped shivering, is confused and has a slow pulse. Why must rescuers move her very gently?',
   'Rough handling can trigger ventricular fibrillation',['Moving her quickly will restart shivering and use up her glucose','Cold makes her bones brittle, so they can fracture with movement','Gentle movement keeps her from waking up too fast'],'C',
   'In severe hypothermia (about 90 °F or 32 °C and below), shivering stops and the cold heart becomes irritable. Jostling can set off ventricular fibrillation. Move the person gently, remove wet clothing and rewarm the core gradually.',ARC_FA),
  q(BASIC,'Which method of removing contaminated gloves follows standard precautions?',
   'Peel the first glove off by its outside, then remove the second from inside its cuff',['Pull both gloves off at the fingertips at the same time, then wash your hands well','Grasp the inside of the first glove with the other gloved hand and peel it off inward','Rinse the gloved hands under running water, then remove both gloves by the fingertips'],'A',
   'Glove-to-glove, then skin-to-skin: the gloved hand touches only the outside of the first glove, and the bare hand touches only the inside of the second. The first glove ends up inside the second. Then dispose of them properly and perform hand hygiene.',DHO),
  q(GEN,'Why does the AHA have rescuers start adult CPR with compressions (C-A-B) instead of breaths?',
   'Blood is still oxygenated early on, so circulation comes first',['Rescue breaths are no longer part of healthcare provider CPR','Compressions open the airway by forcing trapped air out of the lungs','Breaths given first raise the risk of gastric inflation and rib fractures'],'C',
   'In most sudden adult cardiac arrests, the blood is still well oxygenated for the first few minutes. Starting compressions immediately moves that oxygen to the brain and heart and avoids the delay of positioning the airway and getting a barrier device.',AHA_BLS),
  q(INJ,'After a fall, a person has bruising behind both ears and clear fluid draining from one ear. What do these signs most suggest?',
   'A skull fracture',['An ear infection','A mild concussion only','A neck sprain'],'B',
   'Bruising behind the ears (Battle’s sign) and clear fluid (possibly cerebrospinal fluid) from the ears or nose suggest a fracture of the base of the skull. Call 911, suspect a spinal injury, and do not try to stop the fluid from draining.',DHO),
  q(MED,'A 12-year-old who weighs 40 kg (88 lb) is having anaphylaxis. Which epinephrine auto-injector dose is appropriate?',
   '0.3 mg',['0.15 mg','0.5 mg','1 mg'],'B',
   'Epinephrine auto-injectors come in 0.3 mg for adults and children who weigh 30 kg (66 lb) or more, and 0.15 mg for children who weigh about 15–30 kg (33–66 lb). Epinephrine narrows blood vessels and relaxes the airways, reversing the shock and airway swelling of anaphylaxis.',AHA_FA),
  q(CPR,'A rescuer is giving compressions to an adult lying on a soft hospital mattress with no backboard. What is the main concern?',
   'The mattress absorbs force, so compressions may be too shallow',['The mattress will cause the patient’s ribs to break more easily','Compressions on a bed must be given more slowly to allow the mattress to recoil','The AED cannot analyze the heart rhythm accurately on a soft surface'],'D',
   'A soft surface absorbs part of each compression, so the chest may not be compressed the full 2 inches. Use a firm surface or backboard when possible, and push hard enough to reach the target depth.',AHA_BLS),
  q(INJ,'Which first aid action is recommended for a person with a suspected spinal injury who is responsive and breathing?',
   'Keep the person still and support the head by hand, without a collar',['Apply a cervical collar first, then help the person lie flat on a hard surface','Have the person sit up and slowly turn the head side to side','Place a rolled towel under the neck to bring the spine into a straight line'],'A',
   'Current guidelines advise first aid providers not to use cervical collars, which can cause harm. Instead, ask the person to stay still and support the head in the position found, unless the person must be moved for safety or CPR. Call 911.',AHA_FA),
  q(BASIC,'Why is an unresponsive person who is breathing normally placed in the recovery position?',
   'To keep the airway open and let fluids drain from the mouth',['To increase blood flow to the brain and prevent fainting','To make chest compressions easier to start','To protect the spine from injury while waiting for EMS'],'D',
   'In the recovery position, gravity moves the tongue forward and lets vomit or secretions drain out of the mouth instead of into the lungs. Keep checking breathing, and roll the person onto their back to start CPR if breathing stops.',ARC_FA),
  q(CH,'A 9-month-old is choking and cannot cry or cough. Why are abdominal thrusts NOT used for infants?',
   'The large, poorly protected liver and spleen can be injured',['An infant’s airway is too short for abdominal thrusts to create pressure','Abdominal thrusts cause infants to vomit into the airway','Infants should receive only blind finger sweeps'],'C',
   'An infant’s liver is large and sits below a short, flexible rib cage, so abdominal thrusts can cause serious internal injury. Infants receive 5 back blows alternated with 5 chest thrusts. Blind finger sweeps are never used.',AHA_BLS),
  q(ENV,'Which finding suggests deep frostbite rather than frostnip?',
   'Waxy, white or grayish skin that feels hard and numb',['Red skin that tingles and returns to normal when warmed','Shivering with clumsy hand movements','Itchy red patches that appear after cold exposure'],'B',
   'Frostnip is superficial: the skin is red or pale and returns to normal with warming. Deep frostbite freezes tissue, leaving it waxy, white or gray-yellow, hard and numb. Do not rub it, and do not rewarm it if it could refreeze.',AHA_FA),
  q(MED,'Ten minutes after an epinephrine auto-injector was given, a person’s wheezing and facial swelling are returning, and EMS has not yet arrived. A second auto-injector is available. What should be done?',
   'Give the second dose, because symptoms are persisting',['Wait for EMS, because a second dose could cause a heart attack','Give an antihistamine tablet instead of a second dose','Inject the second dose into the same spot as the first'],'A',
   'If anaphylaxis symptoms persist and EMS is delayed more than about 5–10 minutes, a second dose of epinephrine may be given. Inject it into the outer thigh, ideally at a different spot from the first. Antihistamines act too slowly to treat anaphylaxis.',AHA_FA),
  q(AED,'A man collapses beside a pool and is lying in a shallow puddle of water. What should be done before the AED delivers a shock?',
   'Move him out of the standing water and quickly dry his chest',['Nothing, because AEDs are designed to work in standing water','Wait until his clothing and skin have dried completely','Place him on a metal surface to ground the current'],'D',
   'Water conducts electricity, which can divert the shock away from the heart and endanger rescuers. Move the person out of standing water and wipe the chest dry before attaching pads. Do not delay the shock to dry clothing.',AHA_BLS),
  q(INJ,'A teenager’s permanent front tooth is knocked out during a basketball game. Which handling is correct?',
   'Hold it by the crown and store it in milk',['Hold it by the root and scrub it clean','Wrap it in a dry tissue for the dentist','Soak it in tap water for several hours'],'C',
   'Touching or scrubbing the root damages the cells needed to reattach the tooth. Hold it by the crown, rinse it briefly if it is dirty, and keep it in a storage solution such as milk or a balanced salt solution. Get to a dentist quickly, ideally within an hour.',AHA_FA),
  q(CPR,'Rescuers find an unresponsive man with a suspected opioid overdose. He is not breathing and has no pulse. Which action takes priority?',
   'Start high-quality CPR and use an AED; naloxone must not delay CPR',['Give naloxone, then wait 2–3 minutes before starting CPR','Give rescue breaths only, because opioids stop breathing, not the heart','Give naloxone, then check for a pulse every 30 seconds'],'A',
   'Once there is no pulse, the person is in cardiac arrest, and CPR and defibrillation come first. Naloxone may be given, but there is no evidence it helps in cardiac arrest, and it must never delay compressions.',AHA_BLS),
  q(BASIC,'A responsive adult with a sprained ankle must be moved out of a smoke-filled room. Two rescuers are available, and the person can hold on to them. Which move is best?',
   'Two-person seat carry',['Clothes drag','Single-rescuer ankle drag','Blanket drag'],'B',
   'A responsive person who cannot walk but can hold on to the rescuers can be moved with a two-person seat carry. Drags are used mainly for people who are unresponsive or cannot help, such as the clothes drag for a possible spinal injury.',ARC_FA),
  q(GEN,'For basic life support, how should a rescuer classify a 13-year-old girl who shows signs of puberty, such as breast development?',
   'As an adult',['As a child, because she is under 18','As a child until she weighs more than 55 lb (25 kg)','As an infant-to-child transition case'],'C',
   'For BLS, child means age 1 year to puberty. Puberty is shown by breast development in females and underarm hair in males. Once these signs are present, use adult CPR techniques and the 30:2 ratio for any number of rescuers.',AHA_BLS),
  q(MED,'Three family members in a home heated by a gas furnace all wake up with headaches, dizziness and nausea on a winter morning. What should the first aider suspect and do first?',
   'Carbon monoxide poisoning; move everyone to fresh air',['Food poisoning; give them small sips of clear fluids','Influenza; have them rest in a warm, closed room','Dehydration; give each of them an electrolyte drink'],'D',
   'Similar symptoms in several people who share a heated space suggest carbon monoxide, which binds to hemoglobin far more tightly than oxygen. Get everyone into fresh air without putting yourself at risk, call 911, and give CPR if anyone becomes unresponsive and is not breathing normally.',ARC_FA),
  q(INJ,'A deep wound in the groin is bleeding heavily, and a tourniquet cannot be used there. What should the first aider do?',
   'Pack the wound with gauze and hold firm pressure',['Apply a cold pack to slow the bleeding','Raise both legs above the heart and wait for EMS','Press firmly on a pressure point behind the knee'],'B',
   'Wounds at junctions such as the groin, armpit and neck cannot take a tourniquet. Pack the wound tightly with gauze (a hemostatic dressing if available) and hold firm, direct pressure until EMS takes over.',ARC_FA),
  q(ENV,'A swimmer is stung by a jellyfish. After the tentacles are removed, which care is recommended for most stings?',
   'Rinse with vinegar for 30 seconds or more, then use hot water',['Rinse with fresh water, then apply an ice pack for 20 minutes','Rub sand over the area to scrape away the remaining stingers','Apply a pressure bandage tightly over the sting'],'A',
   'Vinegar inactivates stinging cells that have not yet fired. Fresh water and rubbing can make them fire. After the vinegar rinse, soaking in water as hot as can be tolerated, for about 20 minutes, helps relieve pain.',AHA_FA),
  q(ADV,'During adult CPR with an advanced airway, a rescuer squeezes the bag about 25 times per minute. What is the most likely harmful effect?',
   'Less blood returns to the heart as chest pressure rises',['Lower carbon dioxide that makes the heart beat faster','Airway swelling that dislodges the advanced airway','Faster oxygen delivery that causes seizures'],'C',
   'The target is 1 breath every 6 seconds (10 per minute). Excessive ventilation raises pressure inside the chest, which reduces blood return to the heart and the blood flow that compressions produce. Each breath should last about 1 second with just enough volume to make the chest rise.',AHA_BLS),
  q(BASIC,'A responsive adult with a deep cut on his hand refuses your offer of first aid. What should you do?',
   'Respect the refusal, stay nearby and call 911 if needed',['Give care anyway, because the bleeding could become serious','Leave the scene, since a refusal ends any duty you have to him','Ask a bystander to hold his arm still while you bandage it'],'D',
   'A competent adult has the right to refuse care. Giving care anyway could be considered battery. You can still call 911, stay nearby and offer help again if his condition changes.',ARC_FA),
  q(AED,'After analyzing the rhythm, the AED announces “No shock advised.” What should the rescuers do?',
   'Resume CPR immediately, starting with compressions',['Turn the AED off, because the rhythm cannot be shocked','Check for a carotid pulse for a full 30 seconds','Remove the pads and reposition them on the chest'],'B',
   'No shock advised means the rhythm is not shockable (for example, asystole or a rhythm with a pulse); it does not mean the patient is fine. Resume compressions right away, leave the pads on, and let the AED reanalyze in about 2 minutes.',AHA_BLS),
  q(MED,'Why should a first aider NOT give aspirin to a person showing signs of stroke?',
   'Aspirin can worsen bleeding if the stroke is hemorrhagic',['Aspirin raises blood pressure, which can cause a second stroke','Aspirin is too slow to help a person having a stroke','Aspirin can cause dangerous airway swelling in stroke patients'],'A',
   'A first aider cannot tell an ischemic (clot) stroke from a hemorrhagic (bleeding) stroke. Aspirin can worsen bleeding, so it is given only for suspected heart attack, never for stroke signs. Note the time the person was last known well.',AHA_FA),
  q(INJ,'A worker has an open abdominal wound with intestines protruding. What should the first aider do?',
   'Cover the organs with a moist, sterile dressing',['Gently push the organs back inside','Cover them with a dry, fluffy cotton dressing','Give sips of water to prevent dehydration'],'C',
   'Never push protruding organs back in. Cover them with a moist, sterile dressing to keep them from drying out, then cover that loosely. Do not use materials that stick or shed fibers, and give nothing by mouth.',DHO),
  q(CPR,'A lifeguard pulls an unresponsive 10-year-old from a pool. The child is not breathing and has no pulse. Because drowning causes a hypoxic arrest, what does CPR emphasize?',
   'Early rescue breaths combined with compressions',['Abdominal thrusts to drain water from the lungs before any CPR','Compression-only CPR until an AED arrives and analyzes the rhythm','Placing the child in the recovery position so water drains out'],'D',
   'In drowning, the heart stops because of a lack of oxygen, so ventilation is essential. Give rescue breaths early (the Red Cross teaches 2 initial breaths) and combine them with compressions. Do not try to drain water from the lungs.',ARC_BLS+'; '+AHA_BLS),
  q(RB,'A single rescuer ventilates an adult with a bag-mask device using the E-C clamp technique. What do the C and the E represent?',
   'Thumb and index finger seal the mask; the other three fingers lift the jaw',['Thumb and index finger lift the jaw; the other three fingers seal the mask','C is the curved edge of the mask; E is the exhalation valve','C is the chest compressions; E is the exhalation time'],'B',
   'The thumb and index finger form a C to press the mask against the face, while the other three fingers form an E along the bone of the jaw to lift it into the mask and open the airway. Two-rescuer bag-mask ventilation gives a better seal when possible.',AHA_BLS),
  q(ENV,'Within an hour of a spider bite, a person develops severe cramping and rigidity of the abdominal and back muscles. Which spider most likely caused it?',
   'Black widow',['Brown recluse','Tarantula','Wolf spider'],'A',
   'Black widow venom is a neurotoxin that causes painful muscle cramps and rigidity, often in the abdomen, within about an hour. A brown recluse bite instead causes a slowly developing area of tissue death. Wash the bite, apply a cold pack and seek medical care.',ARC_FA)
 ]
};
